    def contact_get_items(
        self,
        folder: str,
        filter: Optional[str] = None,
        orderby: Optional[str] = None,
        top: Optional[int] = None,
        skip: Optional[int] = None,
        *,
        timeout: Optional[float] = None,
        headers: Optional[Mapping[str, str]] = None,
        client_request_id: Optional[str] = None,
        response_hook: Optional[ConnectorResponseHook] = None,
    ) -> AsyncItemPaged[dict[str, Any]]:
        """
        Get contacts

        This operation gets contacts from a contacts folder.

        Returns an Azure Core async pager that follows the connector
        continuation URL.
        """
        request_url = (
            f"{self._connection_runtime_url}"
            f"/codeless"
            f"/v1.0"
            f"/me"
            f"/contactFolders"
            f"/{quote(quote(str(folder), safe=''), safe='')}"
            f"/contacts"
        )
        query_params = []
        if filter is not None:
            value = str(filter)
            if isinstance(filter, bool):
                value = value.lower()
            query_params.append(f"$filter={quote(value, safe='')}")
        if orderby is not None:
            value = str(orderby)
            if isinstance(orderby, bool):
                value = value.lower()
            query_params.append(f"$orderby={quote(value, safe='')}")
        if top is not None:
            value = str(top)
            if isinstance(top, bool):
                value = value.lower()
            query_params.append(f"$top={quote(value, safe='')}")
        if skip is not None:
            value = str(skip)
            if isinstance(skip, bool):
                value = value.lower()
            query_params.append(f"$skip={quote(value, safe='')}")
        if query_params:
            request_url += '?' + '&'.join(query_params)
        initial_request_url = request_url
        request_body = None

        async def get_next(
            continuation_token: Optional[str],
        ) -> tuple[ConnectorResponseSnapshot, str]:
            request_url = continuation_token or initial_request_url
            body = request_body if continuation_token is None else None
            response = await self.http_client.send(
                "GET", request_url, body=body,
                timeout=timeout,
                headers=headers,
                client_request_id=client_request_id,
                response_hook=response_hook,
            )

            if not (200 <= response.status < 300):
                raise ConnectorException(
                    "GET",
                    request_url,
                    response.status,
                    response.text,
                )

            return response, request_url

        async def extract_data(
            page_response: tuple[ConnectorResponseSnapshot, str],
        ) -> tuple[Optional[str], AsyncIterator[dict[str, Any]]]:
            response, request_url = page_response
            page = json.loads(response.text) if response.text else {}
            next_link = page.get("@odata.nextLink")
            continuation_token = (
                self._resolve_pagination_url(next_link, request_url)
                if next_link
                else None
            )

            async def items() -> AsyncIterator[dict[str, Any]]:
                for item in page.get("value", []):
                    yield item

            return continuation_token, items()

        return AsyncItemPaged(get_next, extract_data)

